-- Bible Scroll app tables. Plain SQL, D1/SQLite.
-- Timestamps are Unix epoch milliseconds (INTEGER). Ids are UUIDs generated by the Worker or the client.
-- Canonical passage references use "BOOK.CHAPTER.VERSE" or "BOOK.CHAPTER.VERSE-VERSE" with USFM book ids,
-- e.g. "PSA.23.1" or "MAT.11.28-30". They are translation-independent.

-- ── Profile & preferences ────────────────────────────────────────────────────

CREATE TABLE profiles (
  user_id      TEXT PRIMARY KEY REFERENCES "user" ("id") ON DELETE CASCADE,
  display_name TEXT,
  bio          TEXT,
  avatar_key   TEXT,                          -- R2 object key; bucket is private
  updated_at   INTEGER NOT NULL
);

CREATE TABLE preferences (
  user_id                 TEXT PRIMARY KEY REFERENCES "user" ("id") ON DELETE CASCADE,
  intention               TEXT,               -- onboarding answers; NULL = skipped
  familiarity             TEXT,
  topics                  TEXT NOT NULL DEFAULT '[]',   -- JSON array of topic names
  routine                 TEXT,
  reminders_enabled       INTEGER NOT NULL DEFAULT 0 CHECK (reminders_enabled IN (0, 1)),
  reminder_time           TEXT NOT NULL DEFAULT '08:00' CHECK (reminder_time GLOB '[0-2][0-9]:[0-5][0-9]'),
  time_zone               TEXT,               -- IANA name, e.g. "America/Chicago"
  appearance              TEXT NOT NULL DEFAULT 'dark' CHECK (appearance IN ('light', 'dark', 'system')),
  gradient                TEXT,               -- JSON gradient config; NULL = shipped default
  onboarding_version      INTEGER,
  onboarding_completed_at INTEGER,            -- never cleared by ordinary settings edits
  updated_at              INTEGER NOT NULL
);

-- ── Scripture (canonical text; seeded separately) ───────────────────────────

CREATE TABLE translations (
  id           TEXT PRIMARY KEY,              -- "kjv"
  name         TEXT NOT NULL,
  license      TEXT NOT NULL,                 -- e.g. "Public Domain"
  source_url   TEXT,
  attribution  TEXT
);

CREATE TABLE books (
  id            TEXT PRIMARY KEY,             -- USFM id: "GEN", "PSA", "MAT"
  name          TEXT NOT NULL,
  testament     TEXT NOT NULL CHECK (testament IN ('OT', 'NT')),
  position      INTEGER NOT NULL UNIQUE,      -- canonical order, 1..66
  chapter_count INTEGER NOT NULL CHECK (chapter_count > 0)
);

CREATE TABLE verses (
  translation_id TEXT NOT NULL REFERENCES translations (id),
  book_id        TEXT NOT NULL REFERENCES books (id),
  chapter        INTEGER NOT NULL CHECK (chapter > 0),
  verse          INTEGER NOT NULL CHECK (verse > 0),
  text           TEXT NOT NULL,
  PRIMARY KEY (translation_id, book_id, chapter, verse)
);

-- Prototype ids ("ps23", "pr31", …) mapped to canonical references.
CREATE TABLE passage_aliases (
  alias TEXT PRIMARY KEY,
  ref   TEXT NOT NULL
);

