-- ── Saved passages & reading ────────────────────────────────────────────────

CREATE TABLE saved_passages (
  user_id    TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  ref        TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, ref)                  -- one save per user per passage
);
CREATE INDEX saved_passages_user_created ON saved_passages (user_id, created_at);

-- Immutable. The client generates `id` so retried uploads are idempotent.
-- Streaks are computed from DISTINCT local_day, so several events on one day count once.
CREATE TABLE reading_events (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  local_day   TEXT NOT NULL CHECK (local_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  time_zone   TEXT NOT NULL,
  occurred_at INTEGER NOT NULL,               -- UTC
  ref         TEXT,
  plan_id     TEXT,
  plan_step   INTEGER,
  created_at  INTEGER NOT NULL
);
CREATE INDEX reading_events_user_day ON reading_events (user_id, local_day);

-- ── Reading plans ───────────────────────────────────────────────────────────

CREATE TABLE plans (
  id          TEXT PRIMARY KEY,               -- "quiet", "peace", "strength"
  title       TEXT NOT NULL,
  description TEXT NOT NULL,
  topic       TEXT,
  tone        TEXT,                           -- card color family: sage, lavender, sand
  position    INTEGER NOT NULL,
  published   INTEGER NOT NULL DEFAULT 1 CHECK (published IN (0, 1))
);

CREATE TABLE plan_steps (
  plan_id  TEXT NOT NULL REFERENCES plans (id) ON DELETE CASCADE,
  position INTEGER NOT NULL CHECK (position >= 0),
  ref      TEXT NOT NULL,
  PRIMARY KEY (plan_id, position)
);

CREATE TABLE plan_progress (
  user_id          TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  plan_id          TEXT NOT NULL REFERENCES plans (id),
  started_at       INTEGER NOT NULL,
  current_position INTEGER NOT NULL DEFAULT 0,
  completed_at     INTEGER,
  updated_at       INTEGER NOT NULL,
  PRIMARY KEY (user_id, plan_id)
);

CREATE TABLE plan_step_completions (
  user_id      TEXT NOT NULL,
  plan_id      TEXT NOT NULL,
  position     INTEGER NOT NULL,
  completed_at INTEGER NOT NULL,
  PRIMARY KEY (user_id, plan_id, position),
  FOREIGN KEY (user_id, plan_id) REFERENCES plan_progress (user_id, plan_id) ON DELETE CASCADE
);

