-- ── Membership (written only by verified webhooks) ──────────────────────────

-- No foreign key: a store event can arrive before or after the user row changes (e.g. anonymous → linked).
CREATE TABLE entitlements (
  user_id                 TEXT NOT NULL,
  entitlement             TEXT NOT NULL,      -- 'plus'
  source                  TEXT NOT NULL CHECK (source IN ('app_store', 'play', 'stripe')),
  product_id              TEXT,
  status                  TEXT NOT NULL CHECK (status IN ('trialing', 'active', 'grace', 'expired', 'refunded')),
  current_period_end      INTEGER,
  original_transaction_id TEXT,
  updated_at              INTEGER NOT NULL,
  PRIMARY KEY (user_id, entitlement)
);
CREATE INDEX entitlements_original_transaction ON entitlements (original_transaction_id);

-- Idempotency for webhooks: insert the provider's event id first; a duplicate means "already processed".
CREATE TABLE webhook_events (
  id          TEXT PRIMARY KEY,               -- "<source>:<provider event id>"
  source      TEXT NOT NULL,
  type        TEXT NOT NULL,
  received_at INTEGER NOT NULL
);

-- Append-only: AI calls and other metered features, for quotas and cost per subscriber.
CREATE TABLE usage_ledger (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL,
  feature     TEXT NOT NULL,
  units       INTEGER NOT NULL,
  cost_micros INTEGER NOT NULL,
  created_at  INTEGER NOT NULL
);
CREATE INDEX usage_user_day ON usage_ledger (user_id, created_at);

-- ── Support ─────────────────────────────────────────────────────────────────

CREATE TABLE support_requests (
  id                 TEXT PRIMARY KEY,        -- shown to the user as their reference
  user_id            TEXT NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  category           TEXT NOT NULL,
  message            TEXT NOT NULL CHECK (length(message) BETWEEN 1 AND 5000),
  contact_email      TEXT,
  contact_preference TEXT,
  app_version        TEXT,
  status             TEXT NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'in_progress', 'resolved', 'closed')),
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL
);
CREATE INDEX support_requests_user ON support_requests (user_id, created_at);
